/* eslint-disable no-unused-expressions */
({
  RBESIDFilters: [
    'RBES0101',
    'RBES0102',
    'RBES0103',
    'RBES0104',
    'RBES0105',
    'RBES0106',
    'RBES0107',
    'RBES0111',
    'RBES0704'
  ],

  appPageLocationOptions: ['Home', 'Toolkit', 'Client'],

  countryCodeMap: {'AX': 'ALA', 'AL': 'ALB', 'DZ': 'DZA', 'AS': 'ASM', 'AD': 'AND', 'AO': 'AGO', 'AI': 'AIA', 'AQ': 'ATA', 'AG': 'ATG', 'AE': 'ARE', 'AR': 'ARG', 'AM': 'ARM', 'AW': 'ABW', 'SH': 'SHN', 'AU': 'AUS', 'AT': 'AUT', 'AZ': 'AZE', 'BS': 'BHS', 'BH': 'BHR', 'BD': 'BGD', 'BB': 'BRB', 'BY': 'BLR', 'BE': 'BEL', 'BZ': 'BLZ', 'BJ': 'BEN', 'BM': 'BMU', 'BT': 'BTN', 'BO': 'BOL', 'BA': 'BIH', 'BW': 'BWA', 'BV': 'BVT', 'BR': 'BRA', 'BQ': 'ATB', 'IO': 'IOT', 'BN': 'BRN', 'BG': 'BGR', 'BF': 'BFA', 'BI': 'BDI', 'KH': 'KHM', 'CM': 'CMR', 'CA': 'CAN', 'CV': 'CPV', 'KY': 'CYM', 'CF': 'CAF', 'TD': 'TCD', 'CL': 'CHL', 'CN': 'CHN', 'CX': 'CXR', 'CC': 'CCK', 'CO': 'COL', 'KM': 'COM', 'CG': 'COG', 'CK': 'COK', 'CR': 'CRI', 'HR': 'HRV', 'CU': 'CUB', 'CY': 'CYP', 'CZ': 'CZE', 'DK': 'DNK', 'DJ': 'DJI', 'DM': 'DMA', 'DO': 'DOM', 'TL': 'TLS', 'EC': 'ECU', 'EG': 'EGY', 'SV': 'SLV', 'GQ': 'GNQ', 'ER': 'ERI', 'EE': 'EST', 'ET': 'ETH', 'FK': 'FLK', 'FO': 'FRO', 'FJ': 'FJI', 'FI': 'FIN', 'FR': 'FRA', 'GF': 'GUF', 'PF': 'PYF', 'TF': 'ATF', 'GA': 'GAB', 'GM': 'GMB', 'GE': 'GEO', 'DE': 'DEU', 'GH': 'GHA', 'GI': 'GIB', 'GR': 'GRC', 'GL': 'GRL', 'GD': 'GRD', 'GP': 'GLP', 'GU': 'GUM', 'GT': 'GTM', 'GG': 'GGY', 'GN': 'GIN', 'GW': 'GNB', 'GY': 'GUY', 'HT': 'HTI', 'HM': 'HMD', 'HN': 'HND', 'HK': 'HKG', 'HU': 'HUN', 'IS': 'ISL', 'IN': 'IND', 'ID': 'IDN', 'IR': 'IRN', 'IQ': 'IRQ', 'IE': 'IRL', 'IM': 'IMN', 'IL': 'ISR', 'IT': 'ITA', 'CI': 'CIV', 'JM': 'JAM', 'JP': 'JPN', 'JE': 'JEY', 'JO': 'JOR', 'KZ': 'KAZ', 'KE': 'KEN', 'KI': 'KIR', 'KW': 'KWT', 'KG': 'KGZ', 'LA': 'LAO', 'LV': 'LVA', 'LB': 'LBN', 'LS': 'LSO', 'LR': 'LBR', 'LY': 'LBY', 'LI': 'LIE', 'LT': 'LTU', 'LU': 'LUX', 'MO': 'MAC', 'MK': 'MKD', 'MG': 'MDG', 'MW': 'MWI', 'MY': 'MYS', 'MV': 'MDV', 'ML': 'MLI', 'MT': 'MLT', 'MH': 'MHL', 'MQ': 'MTQ', 'MR': 'MRT', 'MU': 'MUS', 'YT': 'MYT', 'MX': 'MEX', 'MD': 'MDA', 'MC': 'MCO', 'MN': 'MNG', 'ME': 'MNE', 'MS': 'MSR', 'MA': 'MAR', 'MZ': 'MOZ', 'MM': 'MMR', 'NA': 'NAM', 'NR': 'NRU', 'NP': 'NPL', 'AN': 'ANT', 'NL': 'NLD', 'NC': 'NCL', 'NZ': 'NZL', 'NI': 'NIC', 'NE': 'NER', 'NG': 'NGA', 'NU': 'NIU', 'NF': 'NFK', 'KP': 'PRK', 'MP': 'MNP', 'NO': 'NOR', 'OM': 'OMN', 'PK': 'PAK', 'PW': 'PLW', 'PS': 'PSE', 'PA': 'PAN', 'PY': 'PRY', 'PE': 'PER', 'PH': 'PHL', 'PN': 'PCN', 'PL': 'POL', 'PT': 'PRT', 'PR': 'PRI', 'QA': 'QAT', 'RE': 'REU', 'RO': 'ROU', 'RU': 'RUS', 'RW': 'RWA', 'BL': 'BLM', 'KN': 'KNA', 'LC': 'LCA', 'MF': 'MAF', 'PM': 'SPM', 'VC': 'VCT', 'WS': 'WSM', 'SM': 'SMR', 'ST': 'STP', 'SA': 'SAU', 'SN': 'SEN', 'RS': 'SRB', 'SC': 'SYC', 'SL': 'SLE', 'SG': 'SGP', 'SK': 'SVK', 'SI': 'SVN', 'SB': 'SLB', 'SO': 'SOM', 'ZA': 'ZAF', 'GS': 'SGS', 'KR': 'KOR', 'ES': 'ESP', 'LK': 'LKA', 'SD': 'SDN', 'SR': 'SUR', 'SJ': 'SJM', 'SZ': 'SWZ', 'SE': 'SWE', 'CH': 'CHE', 'SY': 'SYR', 'TW': 'TWN', 'TJ': 'TJK', 'TZ': 'TZA', 'TH': 'THA', 'TG': 'TGO', 'TK': 'TKL', 'TO': 'TON', 'TT': 'TTO', 'TN': 'TUN', 'TR': 'TUR', 'TM': 'TKM', 'TC': 'TCA', 'TV': 'TUV', 'UG': 'UGA', 'UA': 'UKR', 'GB': 'GBR', 'UM': 'UMI', 'VI': 'VIR', 'UY': 'URY', 'US': 'USA', 'UZ': 'UZB', 'VU': 'VUT', 'VA': 'VAT', 'VE': 'VEN', 'VN': 'VNM', 'VG': 'VGB', 'WF': 'WLF', 'EH': 'ESH', 'YE': 'YEM', 'ZM': 'ZMB'},

  init: function(cmp, helper) {
    var action = cmp.get('c.getUserBAPermissionSet');
    var callAction = this.promisifyCall(action);
    callAction.then(
      $A.getCallback(function(result) {
        cmp.set('v.userBusinessArea', result);
        [
          'KPICatalog',
          'businessArea',
          'group',
          'sector',
          'bookingCountry',
          'product',
          'client'
        ].forEach((type) => {
          if (
            !helper.appPageLocationOptions.includes(
              cmp.get('v.appPageLocation')
            )
          ) {
            if (cmp.get('v.pageReference').state[ 'c__' + type]) {
              let arrayToInsert = [];
              cmp
                .get('v.pageReference')
                .state[ 'c__' + type].split('-')
                .forEach((urlValue) => {
                  if (!(type === 'businessArea' && urlValue === 'empty')) {
                    arrayToInsert.push(urlValue);
                  } else {
                    arrayToInsert.push('empty');
                  }
                });
              cmp.set('v.' + type + 'Selected', arrayToInsert);
            }
          }
        });
        ['KPICatalog', 'client'].forEach((type) => {
          helper.setMSOptions(cmp, helper, type);
        });
      })
    );
  },
  setMSOptions: function(cmp, helper, type) {
    var catalogId; //KPI_TYPE, CRITERIA_NAME, BUSINESS_AREA, INDUSTRY_GROUP, INDUSTRY_ACTIVITY
    var selected;
    switch (type) {
      case 'KPICatalog': {
        catalogId = 'KPI_TYPE';
        selected = helper.getSelectedOptions(cmp, 'KPICatalog');
        break;
      }
      case 'client': {
        var groups =
          cmp.get('v.appPageLocation') === 'Toolkit'
            ? cmp.get('v.toolkitId')
            : helper.getSelectedOptions(cmp, 'group');
        let params = {
          businessArea: helper.getSelectedOptions(cmp, 'businessArea'),
          sector: helper.getSelectedOptions(cmp, 'sector'),
          KPICatalog: helper.getSelectedOptions(cmp, 'KPICatalog'),
          bookingCountry: helper.getSelectedOptions(cmp, 'bookingCountry'),
          product: helper.getSelectedOptions(cmp, 'product'),
          groupsId: groups,
          client: cmp.get('v.clientId'),
          toolkitId: cmp.get('v.toolkitId')
        };
        helper.getClients(cmp, helper, params, false);
        return;
      }
    }
    var action = cmp.get('c.getKPICatalog');
    action.setParams({
      catalogId: catalogId,
      opSelected: selected
    });
    var callAction = this.promisifyCall(action);
    callAction.then(
      $A.getCallback(function(result) {
        if (result.success === true && result.options.length > 0) {
          let orderedArray = helper.orderArray(result.options);
          if (catalogId === 'BUSINESS_AREA' || catalogId === 'SECTOR_KPI') {
            result.options.push({ value: 'empty', label: 'Sin Asignar' });
          }
          cmp.set('v.' + type + 'Options', orderedArray);
        } else {
          console.error(result);
          helper.showToast(
            'error',
            'Error en el servicio de catalogos de ' + type,
            result.errorMessage
          );
        }
      })
    );
  },
  formatClients: function(cmp, helper, responseData, isKPI) {
    var tableData = [];
    var clientOptionsById = {};
    var groupOptionsById = {};
    var sectorOptionsById = {};
    var productOptionsById = {};
    var countryOptionsById = {};
    var businessAreaOptionsById = {};
    responseData.data.forEach((client) => {
      client.contracts.forEach((contract, index) => {
        if (
          this.RBESIDFilters.includes(
            this.checkUndefined(contract, [
              'sustainabilityFamily',
              'sustainabilityCategory',
              'id'
            ])
          )
        ) {
          productOptionsById = helper.composeMapToFilter(
            helper,
            productOptionsById,
            contract,
            ['product', 'id'],
            ['product', 'description']
          );
          countryOptionsById = helper.composeMapToFilter(
            helper,
            countryOptionsById,
            contract,
            ['country', 'id'],
            ['country', 'description']
          );
          if (
            !businessAreaOptionsById[
              helper.checkUndefined(contract, ['businessArea', 'description'])
            ]
          ) {
            businessAreaOptionsById[
              helper.checkUndefined(contract, ['businessArea', 'description'])
            ] = {
              label: helper.checkUndefined(contract, [
                'businessArea',
                'description'
              ]),
              value: helper.checkUndefined(contract, ['businessArea', 'id'])
            };
          }
          clientOptionsById = helper.composeMapToFilter(
            helper,
            clientOptionsById,
            client,
            [ 'code' ],
            [ 'name' ]
          );
          sectorOptionsById = helper.composeMapToFilter(
            helper,
            sectorOptionsById,
            client,
            ['clientGroup', 'segment', 'subSegment', 'id'],
            ['clientGroup', 'segment', 'subSegment', 'description']
          );
          groupOptionsById = helper.composeMapToFilter(
            helper,
            groupOptionsById,
            client,
            ['clientGroup', 'id'],
            ['clientGroup', 'description']
          );
          var rowData = {
            businessArea: this.checkUndefined(contract, [
              'businessArea',
              'description'
            ]),
            businessAreaId: this.checkUndefined(contract, [
              'businessArea',
              'id'
            ]),
            operationId: this.checkUndefined(contract, [ 'codeLocal' ]),
            sustainableSubCategoryId: this.checkUndefined(contract, [
              'sustainabilityFamily',
              'sustainabilityCategory',
              'id'
            ]),
            group: helper.checkUndefined(client, [
              'clientGroup',
              'description'
            ]),
            groupId: helper.checkUndefined(client, ['clientGroup', 'id']),
            client: this.checkUndefined(client, [ 'name' ]),
            clientId: this.checkUndefined(client, [ 'code' ]),
            initialDate: this.checkUndefined(contract, [ 'initialDate' ]),
            finalDate: this.checkUndefined(contract, [ 'expirationDate' ]),
            initialAmount: this.checkUndefined(contract, [ 'initialMainAmount' ]),
            currency: this.checkUndefined(contract, [ 'productCurrency' ]),
            bookingCountry: this.checkUndefined(contract, [
              'country',
              'description'
            ]),
            bookingCountryId: this.checkUndefined(contract, ['country', 'id']),
            sustainableSubCategory: this.checkUndefined(contract, [
              'sustainabilityFamily',
              'sustainabilityCategory',
              'description'
            ]),
            kpiDetailsId: index,
            contractId: this.checkUndefined(contract, [ 'id' ]),
            sector: this.checkUndefined(client, [
              'clientGroup',
              'segment',
              'subSegment',
              'description'
            ]),
            sectorId: this.checkUndefined(client, [
              'clientGroup',
              'segment',
              'subSegment',
              'id'
            ]),
            product: this.checkUndefined(contract, ['product', 'description']),
            productId: this.checkUndefined(contract, ['product', 'id']),
            sustAgentId: this.checkUndefined(contract, [
              'sustainabilityFamily',
              'sustainabilyAgentId'
            ]),
            sustCoordinator: this.checkUndefined(contract, [
              'sustainabilityFamily',
              'sustainableCoordinator'
            ]),
            sustCoordinatorFee: this.checkUndefined(contract, [
              'sustainabilityFamily',
              'feeSustainableCoordinator'
            ]),
            initialFee: this.checkUndefined(contract, [ 'initialObligationFee' ]),
            initialMargin: this.checkUndefined(contract, [ 'initialMarginFee' ]),
            currentMargin: this.checkUndefined(contract, [ 'currentMargin' ]),
            currentFee: this.checkUndefined(contract, [ 'currentFee' ]),
            activity: this.checkUndefined(client, [
              'clientGroup',
              'activity',
              'description'
            ]),
            origin: this.checkUndefined(contract, [ 'nameOriginSystem' ])
          };
          rowData.editable = helper.isEditableRow(cmp, contract);
        }
        tableData = helper.pushDataToMainTable(tableData, rowData);
      });
    });
    businessAreaOptionsById.vacio = {
      label: 'SIN ASIGNAR',
      value: 'vacio'
    };
    if (tableData.length === 0) {
      cmp.set('v.disabledNext', true);
      cmp.set('v.disabledPrevious', true);
    } else {
      var pageSize = cmp.get('v.pageSize');
      var totalPages = Math.ceil(tableData.length / pageSize);
      cmp.set('v.page', 1);
      cmp.set('v.firstIndex', 1);
      cmp.set('v.secondIndex', 10);
      cmp.set('v.showTable', true);
      cmp.set('v.totalContracts', tableData.length);
      cmp.set('v.numberOfPages', totalPages);
      cmp.set('v.mainTableDataFiltered', tableData.slice(0, pageSize));
      if (!isKPI) {
        cmp.set('v.mainTableData', tableData);
      }
      cmp.set('v.disabledNext', totalPages <= 1);
      cmp.set('v.disabledPrevious', true);
      cmp.set('v.isLoading', false);
      helper.getTransactional(cmp, helper);
    }
    if (!isKPI) {
      helper.setFilters(
        cmp,
        [
          { filter: 'sector', optionList: sectorOptionsById },
          { filter: 'client', optionList: clientOptionsById },
          { filter: 'group', optionList: groupOptionsById },
          { filter: 'product', optionList: productOptionsById },
          { filter: 'bookingCountry', optionList: countryOptionsById },
          { filter: 'businessArea', optionList: businessAreaOptionsById }
        ],
        helper
      );
    }
  },
  pushDataToMainTable: function(tableData, row) {
    var tableToRet = tableData;
    if (row) {
      tableToRet.push(row);
    }
    return tableToRet;
  },
  isEditableRow: function(cmp, contract) {
    return this.checkUndefined(contract, [ 'nameOriginSystem' ]) === 'CLAN' ||
      this.checkUndefined(contract, [ 'nameOriginSystem' ]) === 'Clan (delta)' ||
      this.checkUndefined(contract, ['businessArea', 'description']) !==
        cmp.get('v.userBusinessArea')
      ? false
      : true;
  },
  composeMapToFilter: function(
    helper,
    map,
    objectTocheck,
    idList,
    descriptionList
  ) {
    var objectToReturn = map;
    if (!objectToReturn[helper.checkUndefined(objectTocheck, idList)]) {
      objectToReturn[helper.checkUndefined(objectTocheck, idList)] = {
        label: helper.checkUndefined(objectTocheck, descriptionList),
        value: helper.checkUndefined(objectTocheck, idList)
      };
    }
    return objectToReturn;
  },
  setFilters: function(cmp, filtersToSet, helper) {
    filtersToSet.forEach((filterListById) => {
      var arrayToSet = [];
      var selectValues = cmp.get('v.' + filterListById.filter + 'Selected');
      Object.values(filterListById.optionList).forEach((arrayValue) => {
        if (selectValues.length > 0) {
          if (selectValues.includes(arrayValue.value)) {
            selectValues[
              selectValues.findIndex(
                (secondArrayValue) =>
                  secondArrayValue.value === arrayValue.value
              )
            ] = arrayValue;
          }
        }
        if (arrayValue.label) {
          arrayToSet.push(arrayValue);
        }
      });
      if (arrayToSet.length === 0) {
        helper.showToast(
          'error',
          'No se ha encontrado ningúna opción para ' + filterListById.filter,
          'Esta filtro quedará vacío'
        );
      } else {
        if (selectValues.length > 0) {
          cmp.set(
            'v.' + filterListById.filter + 'SelectedValues',
            selectValues
          );
        }
        cmp.set(
          'v.' + filterListById.filter + 'Options',
          helper.orderArray(arrayToSet)
        );
      }
    });
  },
  getClients: function(cmp, helper, params, isKPI) {
    var action = cmp.get('c.getClients');
    if (params) {
      action.setParams(params);
    }
    var callAction = this.promisifyCall(action);
    callAction.then(
      $A.getCallback(function(result) {
        if (result.success === true) {
          if (result.data.length > 0) {
            helper.formatClients(cmp, helper, result, isKPI);
          } else {
            cmp.set('v.isLoading', false);
            helper.showToast(
              'error',
              'Error en el servicio para obtener los clientes',
              'Error en el servicio para obtener los clientes'
            );
          }
        } else {
          cmp.set('v.isLoading', false);
          if (params) {
            cmp.set('v.mainTableDataFiltered', undefined);
            cmp.set('v.totalContracts', '0');
            cmp.set('v.firstIndex', '0');
            cmp.set('v.secondIndex', '0');
            cmp.set('v.numberOfPages', '0');
            cmp.set('v.disabledPrevious', true);
            cmp.set('v.disabledNext', true);
          } else {
            helper.showToast(
              'error',
              'Error en el servicio para obtener los clientes',
              'Error en el servicio para obtener los clientes'
            );
          }
          return result;
        }
      })
    );
  },
  getCompLocation: function(cmp) {
    var urlPath = 'KPI_Sustanaible_DealsTab';
    var loc;
    if (urlPath.includes('Toolkit')) {
      loc = 'Toolkit';
      cmp.set('v.appPageLocation', 'Toolkit');
      cmp.set('v.showTable', true);
    } else if (urlPath.includes('Account')) {
      loc = 'Client';
      cmp.set('v.clientId', cmp.get('v.recordId'));
      cmp.set('v.appPageLocation', loc);
    } else if (urlPath.includes('KPI_Sustanaible_DealsTab')) {
      loc = 'Tab';
      cmp.set('v.appPageLocation', loc);
    } else {
      loc = 'Home';
      cmp.set('v.appPageLocation', loc);
    }
    return loc;
  },
  getQueryStringParam: function(param) {
    var res;
    var isgroupClient = param === 'client' || param === 'group';
    if (isgroupClient) {
      res = '';
    } else {
      res = [];
    }
    window.location.search
      .substring(1)
      .replaceAll('c__', '')
      .split('&')
      .forEach((keyval) => {
        let [key, val] = keyval.split('=');
        if (key === param) {
          val.split('-').forEach((item) => {
            if (isgroupClient) {
              res.push(item);
            } else {
              res = item;
            }
          });
        }
      });
    return res;
  },
  getSelectedOptions: function(cmp, auraid) {
    return cmp.get('v.' + auraid + 'Selected');
  },
  getSelectedOptionsQueryString: function(cmp, auraid, helper) {
    var options = helper.getSelectedOptions(cmp, auraid);
    var res = '';
    if (options.length > 0) {
      var ids = [];
      options.forEach((option) => {
        ids.push(option);
      });
      res = res += '&c__' + auraid + '=' + ids.join('-');
    }
    return res;
  },
  buttonSearch: function(cmp, helper) {
    var location = cmp.get('v.appPageLocation');
    cmp.set('v.isLoading', true);
    if (location === 'Tab' || location === 'Toolkit') {
      helper.searchOperations(cmp, helper, false);
    } else {
      var urlVar = '/lightning/n/KPI_Sustanaible_DealsTab/?c__doSearch=true&';
      var compUrl = '';
      let eUrl = $A.get('e.force:navigateToURL');
      if (location === 'Toolkit') {
        compUrl += '&c__toolkitId=' + cmp.get('v.recordId');
      }
      [
        'businessArea',
        'sector',
        'KPICatalog',
        'bookingCountry',
        'product',
        'group',
        'client'
      ].forEach((type) => {
        let selectedType = helper.getSelectedOptionsQueryString(
          cmp,
          type,
          helper
        );
        compUrl += selectedType;
      });
      eUrl.setParams({
        url: urlVar + compUrl
      });
      eUrl.fire();
    }
  },
  searchOperations: function(component, helper, kpiChange) {
    var params;
    params = {
      action: 'search',
      businessArea: helper.getSelectedOptions(component, 'businessArea'),
      sector: helper.getSelectedOptions(component, 'sector'),
      KPICatalog: helper.getSelectedOptions(component, 'KPICatalog'),
      bookingCountry: helper.getSelectedOptions(component, 'bookingCountry'),
      product: helper.getSelectedOptions(component, 'product'),
      groupsId: helper.getSelectedOptions(component, 'group'),
      clients: helper.getSelectedOptions(component, 'client'),
      page: component.get('v.page'),
      size: component.get('v.pageSize'),
      toolkitId: component.get('v.toolkitId')
    };
    params.groupsId =
      component.get('v.appPageLocation') === 'Toolkit'
        ? component.get('v.toolkitId')
        : helper.getSelectedOptions(component, 'group');
    if (params.KPICatalog.length > 0 || kpiChange) {
      var result = helper.getClients(component, helper, params, true);
      if (result) {
        if (!result.success) {
          component.set('v.filteredTable', undefined);
        }
      }
    } else {
      helper.composeTable(component, params, helper);
    }
  },
  setClientsByGroup: function(cmp, helper) {
    var mainTableMirror = JSON.parse(
      JSON.stringify(cmp.get('v.mainTableData'))
    );
    var filteredTable = {};
    if (helper.getSelectedOptions(cmp, 'group').length > 0) {
      helper
        .filterTable(mainTableMirror, {
          groupsId: helper.getSelectedOptions(cmp, 'group')
        })
        .forEach((clientElement) => {
          if (clientElement.client && clientElement.clientId) {
            filteredTable[clientElement.clientId] = {
              label: clientElement.client,
              value: clientElement.clientId
            };
          }
        });
    } else {
      helper.filterTable(mainTableMirror, {}).forEach((clientElement) => {
        if (clientElement.client && clientElement.clientId) {
          filteredTable[clientElement.clientId] = {
            label: clientElement.client,
            value: clientElement.clientId
          };
        }
      });
    }
    cmp.set('v.clientOptions', Object.values(filteredTable));
  },
  composeTable: function(cmp, params, helper) {
    var mainTableMirror = JSON.parse(
      JSON.stringify(cmp.get('v.mainTableData'))
    );
    if (cmp.get('v.appPageLocation') === 'Toolkit') {
      params.groupsId = [];
    }
    var filteredTable = helper.filterTable(mainTableMirror, params);
    if (filteredTable === undefined || filteredTable.length === 0) {
      cmp.set('v.mainTableDataFiltered', undefined);
      cmp.set('v.totalContracts', '0');
      cmp.set('v.firstIndex', '0');
      cmp.set('v.secondIndex', '0');
      cmp.set('v.numberOfPages', '0');
      cmp.set('v.disabledPrevious', true);
      cmp.set('v.disabledNext', true);
    } else {
      var page = cmp.get('v.page');
      var pageSize = cmp.get('v.pageSize');
      var indexStart = pageSize * (page - 1);
      var numberOfpages = Math.ceil(filteredTable.length / pageSize);
      var secondIndex =
        indexStart + 10 < filteredTable.length
          ? indexStart + 10
          : filteredTable.length;
      cmp.set('v.firstIndex', indexStart + 1);
      cmp.set(
        'v.secondIndex',
        indexStart + 10 > filteredTable.length
          ? filteredTable.length
          : indexStart + 10
      );
      cmp.set('v.numberOfPages', numberOfpages);
      cmp.set(
        'v.mainTableDataFiltered',
        filteredTable.slice(indexStart, secondIndex)
      );
      cmp.set('v.totalContracts', filteredTable.length);
      cmp.set('v.disabledNext', numberOfpages === page);
      cmp.set('v.disabledPrevious', page <= 1);
      helper.getTransactional(cmp, helper);
    }
    cmp.set('v.isLoading', false);
  },
  filterTable: function(mainTableMirror, params) {
    if (Array.isArray(mainTableMirror)) {
      Object.keys(params).forEach((param) => {
        if (params[param].length > 0) {
          switch (param) {
            case 'businessArea':
              if (params[param].includes('SIN ASIGNAR')) {
                params[param].push(' ');
              }
              mainTableMirror = mainTableMirror.filter((elementList) =>
                params[param].includes(elementList.businessArea)
              );
              break;
            case 'sector':
              mainTableMirror = mainTableMirror.filter((elementList) =>
                params[param].includes(elementList.sectorId)
              );
              break;
            case 'KPICatalog':
              mainTableMirror = mainTableMirror.filter((elementList) =>
                params[param].includes(elementList.KPICatalog)
              );
              break;
            case 'bookingCountry':
              mainTableMirror = mainTableMirror.filter((elementList) =>
                params[param].includes(elementList.bookingCountryId)
              );
              break;
            case 'product':
              mainTableMirror = mainTableMirror.filter((elementList) =>
                params[param].includes(elementList.productId)
              );
              break;
            case 'groupsId':
              mainTableMirror = mainTableMirror.filter((elementList) =>
                params[param].includes(elementList.groupId)
              );
              break;
            case 'clients':
              mainTableMirror = mainTableMirror.filter((elementList) =>
                params[param].includes(elementList.clientId)
              );
              break;
          }
        }
      });
      return mainTableMirror;
    } else {
      return undefined;
    }
  },
  promisifyCall: function(actionCall) {
    return new Promise((resolve, reject) => {
      actionCall.setCallback(this, function(response) {
        const status = response.getState();
        if (status === 'SUCCESS') {
          resolve(response.getReturnValue());
        } else if (status === 'ERROR') {
          var errorCall = response.getError();
          if (errorCall) {
            if (errorCall[0] && errorCall[0].message) {
              reject(Error('Error message: ' + errorCall[0].message));
            }
          } else {
            reject(Error('Unknown error'));
          }
        }
      });
      $A.enqueueAction(actionCall);
    });
  },
  orderArray: function(arrayToOrder) {
    function compare(a, b) {
      if (a.name < b.name || a.Name < b.Name || a.label < b.label) {
        return -1;
      }
      if (a.name > b.name || a.Name > b.Name || a.label > b.label) {
        return 1;
      }
      return 0;
    }
    return arrayToOrder.sort(compare);
  },
  showToast: function(type, title, message) {
    var toastEvent = $A.get('e.force:showToast');
    toastEvent.setParams({
      title: title,
      message: message,
      duration: 5000,
      key: 'info_alt',
      type: type,
      mode: 'dismissible'
    });
    toastEvent.fire();
  },
  resetAllFilters: function(component, helper) {
    [
      'sector',
      'KPICatalog',
      'businessArea',
      'bookingCountry',
      'product',
      'group',
      'client'
    ].forEach((type) => {
      helper.resetFilter(component, type);
    });
    component.set('v.isLoading', true);
    helper.composeTable(component, {}, helper);
    helper.setClientsByGroup(component, helper);
  },
  resetFilter: function(component, auraId) {
    component.set('v.' + auraId + 'SelectedValues', []);
  },
  checkUndefined: function(data, params) {
    try {
      var dynamicData = data;
      params.forEach((param) => {
        dynamicData = dynamicData[param];
      });
      return dynamicData;
    } catch (exception) {
      if (params[0] === 'businessArea' && params[1] === 'description') {
        return ' ';
      }
      return undefined;
    }
  },
  getUserBusinessArea: function(cmp) {
    var action = cmp.get('c.getUserBAPermissionSet');
    var callAction = this.promisifyCall(action);
    callAction.then(
      $A.getCallback(function(result) {
        cmp.set('v.userBusinessArea', result);
      })
    );
  },
  getTransactional: function(cmp, helper) {
    var groupToPass = [];
    var tableFilteredData = cmp.get('v.mainTableDataFiltered');
    tableFilteredData.forEach((data) => {
      if (data.groupId) {
        groupToPass.push(data.groupId);
      }
    });
    var action = cmp.get('c.getTransactionalBankers');
    action.setParams({ groups: groupToPass });
    var callAction = this.promisifyCall(action);
    callAction.then(
      $A.getCallback(function(result) {
        //groupcode-bankername
        if (result) {
          tableFilteredData.forEach((data) => {
            var indexGroup = result.findIndex(
              (x) =>
                x.groupCode === data.groupId &&
                x.country === data.bookingCountry
            );
            var indexGroup2 = result.findIndex(x => x.groupCode === data.groupId && x.countryCode === helper.countryCodeMap[data.bookingCountryId]);
            if (
              indexGroup !== -1 &&
              data.businessArea === 'GLOBAL TRANSACTIONAL BANKING'
            ) {
              data.transactional = result[indexGroup].userName;
            } else if (indexGroup2 !== -1 && data.businessArea === 'GLOBAL TRANSACTIONAL BANKING') {
              data.transactional = result[indexGroup2].userName;
            }
          });
        }
        cmp.set('v.mainTableDataFiltered', tableFilteredData);
      })
    );
  }
});